<?php authorizeAdmin($u); $from=$_GET['from']??date('Y-01-01'); $to=$_GET['to']??date('Y-12-31'); ensure(validDate($from)&&validDate($to)&&$from<=$to,'Revise las fechas del reporte.'); ?>
<p class="page-intro">Consulta solicitudes con fechas de disfrute en el periodo seleccionado y exporta el detalle a Excel mediante CSV.</p><section class="panel form-panel"><form method="get" class="filter-form"><input type="hidden" name="page" value="reports"><label>Desde<input type="date" name="from" value="<?=e($from)?>" required></label><label>Hasta<input type="date" name="to" value="<?=e($to)?>" required></label><button class="button secondary">Consultar</button><a class="button" href="/?page=export&from=<?=e($from)?>&to=<?=e($to)?>"><?=icon('download')?> Exportar CSV</a></form></section><section class="panel"><?php requestTable(rows('SELECT r.*,c.name category,c.family,u.name FROM requests r JOIN categories c ON c.id=r.category_id JOIN users u ON u.id=r.user_id WHERE EXISTS(SELECT 1 FROM request_slots s WHERE s.request_id=r.id AND s.date BETWEEN ? AND ?) ORDER BY r.id DESC LIMIT 200',[$from,$to])); ?></section>
